let umbrales_por_descripcion = datatable(descripcion:string, umbral_minutos:int)
[
    "Datos Tags",             60,
    "Datos 52 peaks",         60,
    "Datos threshold",        60,
    "Datos input",            60,
    "Datos source contants",  60
];

// =====================================
// TUS VIEWS ORIGINALES
// =====================================
let pi_last_record = view () 
{
    SparkLoggingEvent_CL
    | where log_logger_s == "SIRO_POTENCIA"
    and Message has '"log_load_data_notpii"'
    and Message has '"alert": "false"'
    | order by TimeGenerated desc
    | project Message, TimeGenerated, fuente="Not Pii", descripcion="Datos Tags"
    | take 1
};

let data_52_peaks = view () 
{
    SparkLoggingEvent_CL
    | where log_logger_s == "SIRO_POTENCIA"
    and Message has '"log_load_data_52_peaks"'
    and Message has '"alert": "false"'
    | order by TimeGenerated desc
    | project Message, TimeGenerated, fuente="Archivo Manual", descripcion="Datos 52 peaks"
    | take 1
};

let data_threshold = view () 
{
    SparkLoggingEvent_CL
    | where log_logger_s == "SIRO_POTENCIA"
    and Message has '"log_load_data_threshold"'
    and Message has '"alert": "false"'
    | order by TimeGenerated desc
    | project Message, TimeGenerated, fuente="Archivo Manual", descripcion="Datos threshold"
    | take 1
};

let data_inputs = view () 
{
    SparkLoggingEvent_CL
    | where log_logger_s == "SIRO_POTENCIA"
    and Message has '"log_load_data_inputs"'
    and Message has '"alert": "false"'
    | order by TimeGenerated desc
    | project Message, TimeGenerated, fuente="Archivo Manual", descripcion="Datos input"
    | take 1
};

let data_source_contants = view () 
{
    SparkLoggingEvent_CL
    | where log_logger_s == "SIRO_POTENCIA"
    and Message has '"log_load_data_source_contants"'
    and Message has '"alert": "false"'
    | order by TimeGenerated desc
    | project Message, TimeGenerated, fuente="Archivo Manual", descripcion="Datos source contants"
    | take 1
};

let union_tables = view()
{
    union pi_last_record, data_52_peaks, data_threshold, data_inputs, data_source_contants
};

let format_tables = view() {
    union_tables
    | extend json_msg = parse_json(Message)
    | extend ultimo_timestamp_fuente = todatetime(json_msg.timestamp),
             alertar = tostring(json_msg.alert),
             script_ejecutado = tostring(json_msg.root_python_path)
    | project descripcion, fuente, ultimo_timestamp_fuente, alertar, script_ejecutado
};

// =====================================
// ALERTA + COLOR + FALLBACK POR DESCRIPCIÓN
// =====================================

// Último registro real por cada descripción (si existe)
let ultimos_reales = 
    format_tables
    | summarize arg_max(ultimo_timestamp_fuente, *) by descripcion;

// Fallback: si una descripción no tiene registros, igual queremos verla como "No Alertar" (verde)
let fallback =
    datatable(descripcion:string, fuente:string, ultimo_timestamp_fuente:datetime, alertar:string, script_ejecutado:string)
    [
        "Datos Tags",            "Not Pii",        datetime(null), "false", "",
        "Datos 52 peaks",        "Archivo Manual", datetime(null), "false", "",
        "Datos threshold",       "Archivo Manual", datetime(null), "false", "",
        "Datos input",           "Archivo Manual", datetime(null), "false", "",
        "Datos source contants", "Archivo Manual", datetime(null), "false", ""
    ];

// Unimos "reales" + fallback y nos quedamos con el mejor por descripción (prefiere real sobre fallback)
union ultimos_reales, fallback
| extend _pref = iif(isnull(ultimo_timestamp_fuente), 0, 1)
| summarize arg_max(_pref, *) by descripcion
// Traemos umbral por descripción (minutos)
| join kind=leftouter (umbrales_por_descripcion) on descripcion
| extend umbral_minutos = iif(isnull(umbral_minutos), 60, umbral_minutos)
// Diferencia en minutos respecto de ahora (solo para filas reales)
| extend Diferencia_Minutos = datetime_diff('minute', now(), ultimo_timestamp_fuente)
// Estado final:
// - Si no hay timestamp (fila de fallback) -> No Alertar
// - Si el dato es más viejo que el umbral o el JSON trae alert=true -> Alertar
// - En otro caso -> No Alertar
| extend Estado = iif(
    isnull(ultimo_timestamp_fuente),
    "No Alertar",
    iif(Diferencia_Minutos > umbral_minutos or tolower(alertar) == "true", "Alertar", "No Alertar")
)
// Color igual que en los otros casos
| extend Color = iif(Estado == "Alertar", "#FDE2E2", "#EAF4EA")
| project  Estado, Color

