let DefaultSeparator = " <####> ";

let ADBJobs_map = datatable(jobName:string, jobId:string)
[   
    "[CMZ]_[Plan_Mensual]_Lectura_excels",              "544962207674450",
    "[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_PM",        "15311299280777",
    "[CMZ]_[REPORTE_EJECUTIVO]_GENERAR_DMT_BALANCE",    "943969477663499",
    "[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_BG",        "380493699147440"
];

let DefaultStatuses = datatable(Status:string)
[
    "runSucceeded", "runStarted", "runFailed"
];

let format_table = view (){
    ADBJobs_map
    | extend placeholder = 1
    | join kind=inner (DefaultStatuses | extend placeholder = 1) on placeholder
    | extend jobName_Status = strcat(jobName, DefaultSeparator, Status)
    | project jobName_Status
    | extend placeholder = 0
    | evaluate pivot(jobName_Status, min(placeholder))
};

let result_view = view (){
    DatabricksJobs
    | where $__timeFilter(TimeGenerated)
    | extend json_RequestParams = parse_json(RequestParams)
    | mv-expand json_RequestParams
    | extend jobId = tostring(json_RequestParams.jobId)
    | join kind=inner (ADBJobs_map) on $left.jobId == $right.jobId
    | extend TimeGeneratedBin = bin(TimeGenerated, 30m)
    | project TimeGenerated, TimeGeneratedBin, RequestId, jobName, ActionName
    | summarize arg_max(TimeGenerated, *) by RequestId
    | summarize StatusCount = count() by jobName, TimeGeneratedBin, ActionName
    | extend jobName_Status = strcat(jobName, DefaultSeparator, ActionName)
    | order by TimeGeneratedBin desc
    | project jobName_Status, TimeGeneratedBin
    | evaluate pivot(jobName_Status, count())
    | take 200
};

let schema_result_view = view() {
    result_view | getschema
};

let schema_format_table = view() {
    format_table | getschema
};

let columns_to_keep =
    schema_format_table
    | join kind=anti (schema_result_view) on $left.ColumnName == $right.ColumnName
    | project ColumnName;

let format_table_columns_to_keep = view (){
    columns_to_keep
    | extend placeholder = 0
    | evaluate pivot(ColumnName, min(placeholder))
};

let result_view_final = view (){
    result_view
    | extend placeholder = 1
    | join kind=inner (format_table_columns_to_keep | extend placeholder = 1) on placeholder
    | project-away placeholder*
};

// ======================
// 1) Último bin con los textos "succ / started / failed"
// ======================
let ultimo =
    result_view_final
    | extend ['[CMZ]_[REPORTE_EJECUTIVO]_GENERAR_DMT_BALANCE'] =
               strcat(['[CMZ]_[REPORTE_EJECUTIVO]_GENERAR_DMT_BALANCE <####> runSucceeded'], " / ",
                      ['[CMZ]_[REPORTE_EJECUTIVO]_GENERAR_DMT_BALANCE <####> runStarted'], " / ",
                      ['[CMZ]_[REPORTE_EJECUTIVO]_GENERAR_DMT_BALANCE <####> runFailed'])
    | extend ['[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_BG'] =
               strcat(['[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_BG <####> runSucceeded'], " / ",
                      ['[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_BG <####> runStarted'], " / ",
                      ['[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_BG <####> runFailed'])
    | extend ['[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_PM'] =
               strcat(['[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_PM <####> runSucceeded'], " / ",
                      ['[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_PM <####> runStarted'], " / ",
                      ['[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_PM <####> runFailed'])
    | extend ['[CMZ]_[Plan_Mensual]_Lectura_excels'] =
               strcat(['[CMZ]_[Plan_Mensual]_Lectura_excels <####> runSucceeded'], " / ",
                      ['[CMZ]_[Plan_Mensual]_Lectura_excels <####> runStarted'], " / ",
                      ['[CMZ]_[Plan_Mensual]_Lectura_excels <####> runFailed'])
    | top 1 by TimeGeneratedBin desc;

// ======================
// 2) Extraemos "failed" por job
// ======================
let real =
union
(
    ultimo
    | extend parts = split(tostring(['[CMZ]_[Plan_Mensual]_Lectura_excels']), " / ")
    | extend failed = toreal(parts[2])
    | project Job = "[CMZ]_[Plan_Mensual]_Lectura_excels", failed
),
(
    ultimo
    | extend parts = split(tostring(['[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_PM']), " / ")
    | extend failed = toreal(parts[2])
    | project Job = "[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_PM", failed
),
(
    ultimo
    | extend parts = split(tostring(['[CMZ]_[REPORTE_EJECUTIVO]_GENERAR_DMT_BALANCE']), " / ")
    | extend failed = toreal(parts[2])
    | project Job = "[CMZ]_[REPORTE_EJECUTIVO]_GENERAR_DMT_BALANCE", failed
),
(
    ultimo
    | extend parts = split(tostring(['[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_BG']), " / ")
    | extend failed = toreal(parts[2])
    | project Job = "[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_BG", failed
);

// Fallback si no hay filas en la ventana (__timeFilter sin datos)
let fallback = datatable(Job:string, failed:real)
[
    "[CMZ]_[Plan_Mensual]_Lectura_excels",           0,
    "[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_PM",     0,
    "[CMZ]_[REPORTE_EJECUTIVO]_GENERAR_DMT_BALANCE", 0,
    "[CMZ]_[REPORTE_EJECUTIVO]_Orquestacion_BG",     0
];

// ======================
// 3) ALERTA GLOBAL + COLOR (resultado final)
// ======================
union real, fallback
| summarize failed = max(coalesce(failed, 0.0)) by Job
| summarize failed_jobs = sum(iif(failed > 0, 1, 0))
| extend Estado = iif(failed_jobs > 0, "Alertar", "No Alertar")
| extend Color  = iif(Estado == "Alertar", "#FDE2E2", "#EAF4EA")
| project Estado, Color
